import json, sys, collections
S = sys.argv[1]
rules, folded, mp, oq, linux = [], {}, {}, [], []
for g in range(1, 7):
    o = json.load(open(f'{S}/consol/out-{g}.json'))
    for r in o['rules']: r['family'] = g
    rules += o['rules']; folded.update(o.get('folded', {})); mp.update(o['map'])
    for q in o.get('open_questions', []): q['family'] = g; oq.append(q)
    linux += o.get('linux', [])
def res(i):
    while i in folded: i = folded[i]
    return i
by = {r['id']: r for r in rules}
assert len(by) == len(rules), 'dup ids'
for r in rules: r['src'] = list(dict.fromkeys(r['src']))
# windows records mapped to existing rules without NEW
for l in open(f'{S}/win7-map.tsv'):
    if not l.strip(): continue
    rid, mid, note = l.rstrip('\n').split('\t')
    t = res(mp.get(rid, mid) if mid == 'NEW' else mid)
    if t not in by: print('MISSING target', rid, t); continue
    if rid not in by[t]['src']: by[t]['src'].append(rid)
# remap any src to folded? src lists stay on their rules; check coverage
A = {json.loads(l)['id']: json.loads(l) for l in open(f'{S}/all.jsonl')}
W = {json.loads(l)['id']: json.loads(l) for l in open(f'{S}/win7.jsonl')}
allr = {**A, **W}
where = collections.defaultdict(list)
for r in rules:
    for s in r['src']:
        if s not in allr: print('BAD SRC', r['id'], s)
        else: where[s].append(r['id'])
kept = [k for k, v in allr.items() if v['kept']]
un = [k for k in kept if k not in where]
print('rules', len(rules), 'folded', folded, 'unmapped kept', len(un), un[:20])
print('leftout in src', [s for s in where if not allr[s]['kept']][:10])
print(collections.Counter(r['id'].split('-')[0] for r in rules))
print('plat', sum(bool(r.get('plat')) for r in rules), 'OQ', len(oq), 'linux', len(linux))
print(collections.Counter(r['now'][0] for r in rules))
json.dump({'rules': rules, 'folded': folded, 'oq': oq, 'linux': linux, 'where': where}, open(f'{S}/final.json', 'w'), indent=1)
EOF
python3 -I $S/scripts/assemble.py $S

